import type { DatabaseSync } from "node:sqlite";
import { decide, type Failure, type Policy } from "./domain/retry.ts";
import { ProviderError, type MetricsProvider } from "./providers/port.ts";
import { KNOWN_KINDS, isSafeDetail, isSafeStatus, safeName } from "./providers/safe.ts";
import { activeCooldown, extendCooldown, finishRun, getRun, ingestPage, startRun, type Connection, type RunCounters } from "./store.ts";

export type SyncDeps = {
  provider: MetricsProvider;
  now: () => Date;
  /** Espera de verdade em produção; nos testes só anda o relógio. */
  sleep: (ms: number) => Promise<void>;
  policy: Policy;
  /** Teto de páginas por sincronização: um cursor que nunca acaba não vira laço infinito. */
  maxPages: number;
};

/**
 * O que vai para a resposta e para o histórico persistido quando uma sync falha: a categoria e um contexto seguro (o status HTTP e
 * de onde a falha veio, todos de listas fechadas), nunca o texto da mensagem. Mensagens de erro de adapters, de bibliotecas e de
 * rede podem carregar tokens, URLs com credenciais e trechos de corpo.
 */
export function safeFailure(error: unknown): string {
  try {
      return describeFailure(error);
    } catch {
      return "unexpected: Error"; // um erro cujo próprio acesso a name/kind lança não pode derrubar o registro da falha
    }
  }

  function describeFailure(error: unknown): string {
    if (error instanceof ProviderError && KNOWN_KINDS.has(error.kind)) {
      const status = isSafeStatus(error.status) ? ` (${error.status})` : "";
      const detail = isSafeDetail(error.detail) ? `: ${error.detail}` : "";
      return `${error.kind}${status}${detail}`;
    }
    const name = typeof error === "object" && error !== null ? (error as { name?: unknown }).name : undefined;
    return `unexpected: ${safeName(name)}`;
  }

  /**
   * O último instante que o banco sabe guardar e comparar como texto (ano de 4 dígitos). Um Retry-After que passa dele não é
   * encurtado em silêncio, o que autorizaria uma tentativa antes do prazo pedido: o cooldown fica neste limite, e a execução diz isso.
   */
  export const MAX_REPRESENTABLE_MS = Date.UTC(9999, 11, 31, 23, 59, 59, 999);

  type Terminal = { status: "succeeded" | "failed" | "deferred"; error: string | null; retryAt: string | null };

  /**
   * Sincroniza as métricas de uma conexão numa janela de publicação [since, until].
   *
   * A rede e a espera acontecem FORA de qualquer transação; cada página é gravada numa transação curta e idempotente
   * (`ingestPage`). Por isso uma falha no meio guarda o que já chegou, e repetir a sync (ou rodar duas ao mesmo tempo, ou
   * com janelas que se sobrepõem) não conta nenhum snapshot duas vezes.
   */
  export async function syncConnection(db: DatabaseSync, deps: SyncDeps, connection: Connection, window: { since: string; until: string }) {
    const runId = startRun(db, connection.id, window, deps.now());
    const counters: RunCounters = { attempts: 0, pages: 0, received: 0, new_snapshots: 0, duplicates: 0, stale: 0, conflicts: 0, invalid: 0, waits_ms: [] };
    let terminal: Terminal = { status: "succeeded", error: null, retryAt: null };
    let cursor: string | null = null;
    const seenCursors = new Set<string>();

    try {
    pages: while (true) {
      if (counters.pages >= deps.maxPages) {
        terminal = { status: "failed", error: "too_many_pages", retryAt: null };
        break;
      }

      let attempt = 0;
      let page;
      while (true) {
        // O prazo de um Retry-After vale entre sincronizações, reinícios e conexões ao banco, e é lido antes de CADA chamada externa,
        // inclusive a repetição depois do backoff: outra sync pode ter gravado um prazo enquanto esta dormia. A rede fica fora de
        // transação, então não há atomicidade entre a leitura e a chamada (limite declarado no README).
        const cooling = activeCooldown(db, connection.id, deps.now());
        if (cooling) {
          terminal = { status: "deferred", error: "cooldown_active", retryAt: cooling };
          break pages;
        }
        attempt += 1;
        counters.attempts += 1;
        try {
          page = await deps.provider.fetchPosts({ account: connection.account_id, token: connection.token, since: window.since, until: window.until, cursor });
          break;
        } catch (error) {
          if (!(error instanceof ProviderError)) {
            terminal = { status: "failed", error: safeFailure(error), retryAt: null };
            break pages;
          }
          const failure: Failure = { kind: error.kind, retryAfterMs: error.retryAfterMs };
          const decision = decide(failure, attempt, deps.policy);
          if (decision.action === "retry") {
            counters.waits_ms.push(decision.waitMs);
            await deps.sleep(decision.waitMs);
            continue;
          }
          if (decision.action === "defer") {
            // O provedor pediu um prazo que passa do teto de espera (ou as tentativas acabaram): não esperamos além do teto e
            // não tentamos antes do que ele pediu. A sync termina adiada, com a hora em que vale tentar de novo.
            const requestedAt = deps.now().getTime() + decision.retryAfterMs;
            const beyondLimit = requestedAt > MAX_REPRESENTABLE_MS;
            extendCooldown(db, connection.id, new Date(beyondLimit ? MAX_REPRESENTABLE_MS : requestedAt).toISOString());
            // O prazo devolvido é o EFETIVO (o maior entre o deste 429 e o que outra sync já tenha gravado).
            const effective = (db.prepare("SELECT cooldown_until FROM connections WHERE id = ?").get(connection.id) as { cooldown_until: string }).cooldown_until;
            terminal = { status: "deferred", error: `rate_limited: o provedor pediu para esperar ${decision.retryAfterMs} ms${beyondLimit ? ` (acima do máximo representável; cooldown fixado em ${new Date(MAX_REPRESENTABLE_MS).toISOString()})` : ""}`, retryAt: effective };
            break pages;
          }
          terminal = { status: "failed", error: safeFailure(error), retryAt: null };
          break pages;
        }
      }

      const stored = ingestPage(db, connection.id, runId, page.items, deps.now());
      counters.pages += 1;
      counters.received += page.items.length;
      counters.invalid += page.invalid;
      counters.new_snapshots += stored.new_snapshots;
      counters.duplicates += stored.duplicates;
      counters.stale += stored.stale;
      counters.conflicts += stored.conflicts;

      if (page.nextCursor === null) break;
      if (seenCursors.has(page.nextCursor)) {
        terminal = { status: "failed", error: "pagination_loop", retryAt: null };
        break;
      }
      seenCursors.add(page.nextCursor);
      cursor = page.nextCursor;
    }

  } catch (error) {
    // Nada que dê errado entre startRun e finishRun pode deixar a execução em "running" para sempre.
    terminal = { status: "failed", error: safeFailure(error), retryAt: null };
  }

  finishRun(db, runId, { ...terminal, finishedAt: deps.now() }, counters);
  return getRun(db, runId);
}

test/concurrency.test.ts.source:
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, it } from "vitest";
import { openDatabase } from "../src/db.ts";
import type { PostSnapshot } from "../src/domain/types.ts";
import { createConnection } from "../src/store.ts";
import { snap } from "./fakes.ts";
import { tsWorker } from "./spawn-worker.ts";

const dir = mkdtempSync(join(tmpdir(), "metricas-"));
afterAll(() => rmSync(dir, { recursive: true, force: true }));

type Job = { window: { since: string; until: string }; posts: PostSnapshot[] };

/** Um worker por sincronização; todos esperam na barreira e largam juntos. Se um worker morrer antes da barreira, o teste falha na hora, com o erro. */
async function race(path: string, connectionId: string, jobs: Job[]) {
  const barrier = new SharedArrayBuffer(8);
  const flags = new Int32Array(barrier);
  let failure: Error | null = null;
  const done = jobs.map(
    (job) =>
      new Promise<{ new_snapshots: number; duplicates: number; stale: number; status: string }>((resolve, reject) => {
        const worker = tsWorker(new URL("./race-worker.ts", import.meta.url), { path, connectionId, barrier, ...job });
        worker.once("message", resolve);
        worker.once("error", (error) => {
          failure = error;
          reject(error);
        });
      }),
  );
  done.forEach((promise) => promise.catch(() => {}));
  while (Atomics.load(flags, 1) < jobs.length) {
    if (failure) throw failure;
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
  Atomics.store(flags, 0, 1);
  Atomics.notify(flags, 0);
  return Promise.all(done);
}

function freshConnection(name: string) {
  const path = join(dir, name);
  const db = openDatabase(path);
  const connection = createConnection(db, { id: "con_1", provider: "instagram", accountId: "acc_1", token: "tok" }, () => new Date("2026-06-01T12:00:00.000Z"));
  if (!connection.ok) throw new Error("conexão não criada");
  db.close();
  return path;
}

const T1 = "2026-06-01T12:00:00.000Z";
const posts = ["2026-05-20", "2026-05-22", "2026-05-24", "2026-05-26"].map((day, i) => snap(`p${i + 1}`, `${day}T10:00:00.000Z`, T1, 1000 * (i + 1)));
const window = (from: string, to: string) => ({ since: `${from}T00:00:00.000Z`, until: `${to}T23:59:59.999Z` });

describe("sincronizações simultâneas da mesma conexão, largando juntas", () => {
  it("janelas que se sobrepõem, ao mesmo tempo: cada snapshot entra uma vez e o total é o de cada post uma vez, 10 vezes em bancos novos", async () => {
    for (let round = 0; round < 10; round += 1) {
      const path = freshConnection(`sobrepoe-${round}.sqlite`);
      const jobs: Job[] = [
        { window: window("2026-05-19", "2026-05-23"), posts }, // p1, p2
        { window: window("2026-05-21", "2026-05-25"), posts }, // p2, p3
        { window: window("2026-05-19", "2026-05-27"), posts }, // p1..p4
        { window: window("2026-05-23", "2026-05-27"), posts }, // p3, p4
      ];
      const runs = await race(path, "con_1", jobs);

      expect(runs.map((r) => r.status), `rodada ${round}`).toEqual(["succeeded", "succeeded", "succeeded", "succeeded"]);
      expect(runs.reduce((s, r) => s + r.new_snapshots, 0), `rodada ${round}: cada snapshot é novo exatamente uma vez`).toBe(4);
      expect(runs.reduce((s, r) => s + r.duplicates, 0)).toBe(2 + 2 + 4 + 2 - 4);

      const db = openDatabase(path);
      expect(db.prepare("SELECT COUNT(*) AS n FROM metric_snapshots").get()).toEqual({ n: 4 });
      expect(db.prepare("SELECT COUNT(*) AS posts, SUM(views) AS views FROM posts").get()).toEqual({ posts: 4, views: 10_000 });
      db.close();
    }
  }, 90_000);

  it("snapshot novo e snapshot atrasado do mesmo post, ao mesmo tempo: o número final é sempre o do mais novo", async () => {
    for (let round = 0; round < 10; round += 1) {
      const path = freshConnection(`ordem-${round}.sqlite`);
      const newer = snap("p1", "2026-05-20T10:00:00.000Z", "2026-06-01T13:00:00.000Z", 5000);
      const older = snap("p1", "2026-05-20T10:00:00.000Z", "2026-06-01T09:00:00.000Z", 900);
      const w = window("2026-05-01", "2026-05-31");
      await race(path, "con_1", [
        { window: w, posts: [older] },
        { window: w, posts: [newer] },
        { window: w, posts: [older] },
        { window: w, posts: [newer] },
      ]);
      const db = openDatabase(path);
      expect(db.prepare("SELECT views, as_of FROM posts").get(), `rodada ${round}`).toEqual({ views: 5000, as_of: "2026-06-01T13:00:00.000Z" });
      expect(db.prepare("SELECT COUNT(*) AS n FROM metric_snapshots").get()).toEqual({ n: 2 });
      db.close();
    }
  }, 90_000);
});

test/cooldown.test.ts.source:
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, it } from "vitest";
import { openDatabase } from "../src/db.ts";
import { extendCooldown, getConnection } from "../src/store.ts";
import { tsWorker } from "./spawn-worker.ts";
import { createApp } from "../src/app.ts";
import { FakeClock, FakeProvider, limited, network, snap, timeout } from "./fakes.ts";
import { ALL, DEFAULT_POLICY, setup } from "./helpers.ts";

const dir = mkdtempSync(join(tmpdir(), "metricas-cooldown-"));
afterAll(() => rmSync(dir, { recursive: true, force: true }));
const P1 = "2026-05-20T10:00:00.000Z";
const T1 = "2026-06-01T11:00:00.000Z";
const START = "2026-06-01T12:00:00.000Z";
const READY = "2026-06-01T12:02:00.000Z"; // START + 120 s

/** Conexão cuja primeira sync recebe um 429 com Retry-After de 120 s (o teto padrão é 30 s: a sync é adiada). */
async function deferred(options: Parameters<typeof setup>[0] = {}) {
  const t = setup(options);
  t.provider.posts = [snap("p1", P1, T1, 1000)];
  const id = await t.connect();
  t.provider.failNext(limited(120_000));
  const first = await t.sync(id);
  return { t, id, first };
}

describe("o prazo do Retry-After vale entre sincronizações", () => {
  it("depois de um 429 adiado, uma nova sync antes do prazo não chama o provedor e devolve o mesmo prazo", async () => {
    const { t, id, first } = await deferred();
    expect(first.body).toMatchObject({ status: "deferred", retry_at: READY });
    const callsBefore = t.provider.calls.length;

    t.clock.set("2026-06-01T12:00:30.000Z");
    const blocked = await t.sync(id);
    expect(blocked.status).toBe(202);
    expect(blocked.body).toMatchObject({ status: "deferred", error: "cooldown_active", retry_at: READY, attempts: 0, pages: 0, new_snapshots: 0 });
    expect(t.provider.calls).toHaveLength(callsBefore);
    expect(t.clock.waits).toEqual([]);
  });

  it("uma janela diferente também fica bloqueada: o limite é da conta, não da janela", async () => {
    const { t, id } = await deferred();
    const blocked = await t.sync(id, { since: "2026-05-01T00:00:00.000Z", until: "2026-05-31T00:00:00.000Z" });
    expect(blocked.body).toMatchObject({ status: "deferred", error: "cooldown_active" });
    expect(t.provider.calls).toHaveLength(1);
  });

  it("no instante do prazo a sync volta a rodar", async () => {
    const { t, id } = await deferred();
    t.clock.set(READY);
    const run = await t.sync(id);
    expect(run.body.status).toBe("succeeded");
    expect((await t.metrics(id)).body.totals.views).toBe(1000);
  });

  it("um instante antes do prazo ainda bloqueia", async () => {
    const { t, id } = await deferred();
    t.clock.set("2026-06-01T12:01:59.999Z");
    expect((await t.sync(id)).body).toMatchObject({ status: "deferred", error: "cooldown_active" });
  });

  it("a sync bloqueada fica no histórico, e o prazo aparece nas métricas da conexão", async () => {
    const { t, id } = await deferred();
    await t.sync(id);
    const runs = (await t.runs(id)).body;
    expect(runs).toHaveLength(2);
    expect(runs[0]).toMatchObject({ status: "deferred", error: "cooldown_active", attempts: 0, retry_at: READY });
    expect((await t.metrics(id)).body.cooldown_until).toBe(READY);
    t.clock.set(READY);
    expect((await t.metrics(id)).body.cooldown_until).toBeNull(); // já passou
  });

  it("um 429 que cabe no teto de espera (esperou e deu certo) não deixa cooldown nenhum", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000)];
    const id = await t.connect();
    t.provider.failNext(limited(5_000));
    expect((await t.sync(id)).body.status).toBe("succeeded");
    expect((await t.metrics(id)).body.cooldown_until).toBeNull();
    expect((await t.sync(id)).body.status).toBe("succeeded");
  });

  it("outra conexão (outra conta) não é afetada", async () => {
    const { t, id } = await deferred();
    const other = await t.connect("tiktok", "acc_2");
    expect((await t.sync(other)).body.status).toBe("succeeded");
    expect((await t.sync(id)).body.error).toBe("cooldown_active");
  });

  it("depois que o prazo passa, uma falha comum (sem Retry-After) não deixa cooldown", async () => {
    const { t, id } = await deferred();
    t.clock.set(READY);
    t.provider.failNext(limited(null), limited(null), limited(null), limited(null));
    const run = await t.sync(id);
    expect(run.body.status).toBe("failed");
    expect((await t.metrics(id)).body.cooldown_until).toBeNull();
  });
});

describe("persiste: reinício e outra conexão ao banco", () => {
  it("depois de reiniciar (outra instância sobre o mesmo arquivo, relógio e provedor novos) o prazo continua valendo", async () => {
    const path = join(dir, "reinicio.db");
    const first = setup({ db: openDatabase(path) });
    first.provider.posts = [snap("p1", P1, T1, 1000)];
    const id = await first.connect();
    first.provider.failNext(limited(120_000));
    expect((await first.sync(id)).body.status).toBe("deferred");
    first.db.close();

    const second = setup({ db: openDatabase(path), start: "2026-06-01T12:00:10.000Z" });
    second.provider.posts = [snap("p1", P1, T1, 1000)];
    const blocked = await second.sync(id);
    expect(blocked.body).toMatchObject({ status: "deferred", error: "cooldown_active", retry_at: READY });
    expect(second.provider.calls).toHaveLength(0);
    second.clock.set(READY);
    expect((await second.sync(id)).body.status).toBe("succeeded");
  });

  it("outra instância do serviço sobre o mesmo banco, com a conexão cadastrada pela primeira, respeita o prazo", async () => {
    const path = join(dir, "duas-instancias.db");
    const a = setup({ db: openDatabase(path) });
    a.provider.posts = [snap("p1", P1, T1, 1000)];
    const id = await a.connect();
    const b = setup({ db: openDatabase(path) });
    a.provider.failNext(limited(120_000));
    await a.sync(id);
    expect((await b.sync(id)).body).toMatchObject({ status: "deferred", error: "cooldown_active" });
    expect(b.provider.calls).toHaveLength(0);
  });

  it("outra sync já em andamento cria o prazo no meio: esta para antes da próxima página, guardando o que já chegou", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1), snap("p2", P1, T1, 2), snap("p3", P1, T1, 4)];
    t.provider.pageSize = 2;
    const id = await t.connect();
    const original = t.provider.fetchPosts.bind(t.provider);
    t.provider.fetchPosts = async (request) => {
      const result = await original(request);
      if (t.provider.calls.length === 1) extendCooldown(t.db, id, READY); // outra sync recebeu 429 enquanto esta lia a página 1
      return result;
    };
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "deferred", error: "cooldown_active", retry_at: READY, pages: 1, new_snapshots: 2 });
    expect((await t.metrics(id)).body.totals.views).toBe(3);
    expect(t.provider.calls).toHaveLength(1);
  });
});

describe("o prazo não regride", () => {
  it("um prazo mais curto depois de um mais longo não o encurta; um mais longo o estende", async () => {
    const t = setup();
    const id = await t.connect();
    extendCooldown(t.db, id, "2026-06-01T12:10:00.000Z");
    extendCooldown(t.db, id, "2026-06-01T12:05:00.000Z");
    expect(getConnection(t.db, id)!.cooldown_until).toBe("2026-06-01T12:10:00.000Z");
    extendCooldown(t.db, id, "2026-06-01T12:20:00.000Z");
    expect(getConnection(t.db, id)!.cooldown_until).toBe("2026-06-01T12:20:00.000Z");
  });

  it("4 conexões ao banco estendendo o prazo ao mesmo tempo, 12 vezes: sempre fica o maior", async () => {
    for (let round = 0; round < 12; round += 1) {
      const path = join(dir, `corrida-${round}.db`);
      const seed = setup({ db: openDatabase(path) });
      const id = await seed.connect();
      seed.db.close();

      const barrier = new SharedArrayBuffer(8);
      const flags = new Int32Array(barrier);
      const untils = ["2026-06-01T12:03:00.000Z", "2026-06-01T12:09:00.000Z", "2026-06-01T12:05:00.000Z", "2026-06-01T12:01:00.000Z"];
      const done = untils.map(
        (until) =>
          new Promise<void>((resolve, reject) => {
            const worker = tsWorker(new URL("./cooldown-worker.ts", import.meta.url), { path, connectionId: id, until, barrier });
            worker.once("message", () => resolve());
            worker.once("error", reject);
          }),
      );
      done.forEach((p) => p.catch(() => {}));
      while (Atomics.load(flags, 1) < untils.length) await new Promise((resolve) => setTimeout(resolve, 5));
      Atomics.store(flags, 0, 1);
      Atomics.notify(flags, 0);
      await Promise.all(done);

      const check = openDatabase(path);
      expect(getConnection(check, id)!.cooldown_until, `rodada ${round}`).toBe("2026-06-01T12:09:00.000Z");
      check.close();
    }
  }, 60_000);
});

describe("casos extremos do prazo", () => {
  const DAY = 24 * 60 * 60 * 1000;

  const LIMIT = "9999-12-31T23:59:59.999Z";

  it("Retry-After de 7 dias e 1 ms vale por inteiro: o prazo não é encurtado", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000)];
    const id = await t.connect();
    t.provider.failNext(limited(7 * DAY + 1));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "deferred", retry_at: new Date(Date.parse(START) + 7 * DAY + 1).toISOString() });
    expect(run.body.error).toBe(`rate_limited: o provedor pediu para esperar ${7 * DAY + 1} ms`);
    t.clock.set(new Date(Date.parse(START) + 7 * DAY).toISOString());
    expect((await t.sync(id)).body).toMatchObject({ error: "cooldown_active" });
  });

  it.each([[9_000_000_000_000_000], [300_000_000_000_000]])("Retry-After de %s ms passa do que o banco representa: o cooldown fica no limite, dito na execução, e nada é antecipado", async (ms) => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000)];
    const id = await t.connect();
    t.provider.failNext(limited(ms));
    const run = await t.sync(id);
    expect(run.status).toBe(202);
    expect(run.body).toMatchObject({ status: "deferred", retry_at: LIMIT });
    expect(run.body.error).toBe(`rate_limited: o provedor pediu para esperar ${ms} ms (acima do máximo representável; cooldown fixado em ${LIMIT})`);
    expect(run.body.finished_at).not.toBeNull();
    t.clock.set("2100-01-01T00:00:00.000Z");
    const blocked = await t.sync(id);
    expect(blocked.body).toMatchObject({ error: "cooldown_active", retry_at: LIMIT });
    expect(t.provider.calls).toHaveLength(1);
    expect((await t.runs(id)).body.every((r: any) => r.status !== "running")).toBe(true);
  });

  it("o limite é exato: o último milissegundo representável ainda é o prazo pedido, e um a mais cai na mensagem de limite", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000)];
    const id = await t.connect();
    const exact = Date.UTC(9999, 11, 31, 23, 59, 59, 999) - Date.parse(START);
    t.provider.failNext(limited(exact));
    const first = await t.sync(id);
    expect(first.body).toMatchObject({ retry_at: LIMIT, error: `rate_limited: o provedor pediu para esperar ${exact} ms` });
    const t2 = setup();
    const id2 = await t2.connect();
    t2.provider.failNext(limited(exact + 1));
    expect((await t2.sync(id2)).body.error).toContain("acima do máximo representável");
  });

  it("uma exceção no meio da sync não deixa a execução em 'running': termina 'failed' com a classe do erro", async () => {
    const t = setup();
    const id = await t.connect();
    const hostile = { get name(): string { throw new Error("getter hostil"); } } as unknown as Error;
    t.provider.failNext(hostile);
    const run = await t.sync(id);
    expect(run.status).toBe(502);
    expect(run.body).toMatchObject({ status: "failed", error: "unexpected: Error" });
    expect((await t.runs(id)).body[0].status).toBe("failed");
  });

  it("o retry_at devolvido é o cooldown efetivo (o maior), mesmo que outra sync tenha estendido o prazo no meio", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000)];
    const id = await t.connect();
    const original = t.provider.fetchPosts.bind(t.provider);
    t.provider.fetchPosts = async (request) => {
      extendCooldown(t.db, id, "2026-06-01T12:10:00.000Z"); // outra sync, com Retry-After maior, terminou antes
      return original(request);
    };
    t.provider.failNext(limited(120_000));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "deferred", retry_at: "2026-06-01T12:10:00.000Z" });
  });

  it("extendCooldown normaliza o formato: sem milissegundos ou com offset não derruba a comparação", async () => {
    const t = setup();
    const id = await t.connect();
    extendCooldown(t.db, id, "2026-06-01T12:02:00.000Z");
    extendCooldown(t.db, id, "2026-06-01T12:01:00Z"); // formato sem milissegundos, mais cedo
    expect(getConnection(t.db, id)!.cooldown_until).toBe("2026-06-01T12:02:00.000Z");
    extendCooldown(t.db, id, "2026-06-01T10:03:00-03:00"); // 13:03Z, mais tarde
    expect(getConnection(t.db, id)!.cooldown_until).toBe("2026-06-01T13:03:00.000Z");
    expect(() => extendCooldown(t.db, id, "não é data")).toThrow();
  });
});

describe("token da conexão", () => {
  it.each([["com caractere fora do ASCII imprimível", "tok☃"], ["com quebra de linha", "tok\nx"], ["com espaço no meio", "tok x"]])("%s é 400 no cadastro", async (_name, token) => {
    const t = setup();
    const res = await t.call("POST", "/connections", { provider: "instagram", account_id: "acc_9", token });
    expect(res.status).toBe(400);
    expect(res.body).toMatchObject({ error: "validation_error", field: "token" });
  });
});


describe("falha inesperada dentro da sync", () => {
  it("um erro fora do provedor (aqui, o sleep) não deixa a execução em running e só registra a classe", async () => {
    const clock = new FakeClock(START);
    const db = openDatabase(":memory:");
    const provider = new FakeProvider(clock);
    provider.posts = [snap("p1", P1, T1, 1000)];
    const app = createApp({
      db,
      providerFor: () => provider,
      now: clock.now,
      sleep: async () => {
        throw new TypeError("segredo-no-texto tok-super-secreto");
      },
      policy: DEFAULT_POLICY,
      maxPages: 50,
    });
    const post = (path: string, body: unknown) =>
      app.request(path, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
    const created = (await (await post("/connections", { provider: "instagram", account_id: "acc_1", token: "tok-super-secreto" })).json()) as any;
    provider.failNext(timeout());
    const res = await post(`/connections/${created.id}/sync`, ALL);
    const run = (await res.json()) as any;
    expect(run.status).toBe("failed");
    expect(run.error).toBe("unexpected: TypeError");
    expect(run.finished_at).not.toBeNull();
    expect(JSON.stringify(run)).not.toContain("segredo");
  });
});

describe("cooldown gravado por outra sync durante o backoff", () => {
  const WINDOW_ALL = ALL;
  const makeApp = (hook: (db: ReturnType<typeof openDatabase>, id: () => string, clock: FakeClock) => void) => {
    const clock = new FakeClock(START);
    const db = openDatabase(":memory:");
    const provider = new FakeProvider(clock);
    let connectionId = "";
    const app = createApp({
      db,
      providerFor: () => provider,
      now: clock.now,
      sleep: async (ms: number) => {
        hook(db, () => connectionId, clock);
        await clock.sleep(ms);
      },
      policy: DEFAULT_POLICY,
      maxPages: 50,
    });
    const post = async (path: string, body: unknown) => (await app.request(path, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) })).json() as Promise<any>;
    return { app, db, clock, provider, post, setId: (id: string) => (connectionId = id) };
  };

  it("a nova tentativa relê o prazo: termina adiada, sem nova chamada, e mantém as páginas já gravadas", async () => {
    const t = makeApp((db, id) => extendCooldown(db, id(), "2026-06-01T12:10:00.000Z"));
    t.provider.pageSize = 1;
    t.provider.posts = [snap("p1", P1, T1, 100), snap("p2", P1, T1, 200)];
    const id = (await t.post("/connections", { provider: "instagram", account_id: "acc_1", token: "tok-ok" })).id as string;
    t.setId(id);
    t.provider.failOnCall(2, network()); // a 1ª página entra; a 2ª falha de rede e entra em backoff
    const run = await t.post(`/connections/${id}/sync`, WINDOW_ALL);
    expect(run).toMatchObject({ status: "deferred", error: "cooldown_active", retry_at: "2026-06-01T12:10:00.000Z", pages: 1, new_snapshots: 1 });
    expect(t.provider.calls).toHaveLength(2); // a 1ª página e a 2ª que falhou; a repetição não foi feita
    const metrics = (await (await t.app.request(`/connections/${id}/metrics`)).json()) as any;
    expect(metrics.totals.views).toBe(100);
  });
});

