import { describe, expect, it } from "vitest";
import { ALL, setup } from "./helpers.ts";
import { client, limited, network, server, snap, timeout } from "./fakes.ts";

const T1 = "2026-06-01T12:00:00.000Z";
const P1 = "2026-05-20T10:00:00.000Z";
const P2 = "2026-05-25T10:00:00.000Z";
const P3 = "2026-05-30T10:00:00.000Z";

describe("a primeira sincronização", () => {
  it("guarda os posts, soma os totais e diz quando cada métrica foi buscada", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, "2026-06-01T11:55:00.000Z", 1000, { likes: 10 }), snap("p2", P2, "2026-06-01T11:55:00.000Z", 2000, { likes: 20 })];
    const id = await t.connect();

    const run = await t.sync(id);
    expect(run.status).toBe(200);
    expect(run.body).toMatchObject({ status: "succeeded", attempts: 1, pages: 1, received: 2, new_snapshots: 2, duplicates: 0, stale: 0, invalid: 0, waits_ms: [] });

    const { body } = await t.metrics(id);
    expect(body.totals).toEqual({ posts: 2, views: 3000, likes: 30, comments: 0, shares: 0 });
    expect(body.connection).toEqual({ id, provider: "instagram", account_id: "acc_1" });
    expect(body.last_fetched_at).toBe(T1);
    // as_of é o horário da métrica no provedor; fetched_at é quando o NOSSO relógio buscou. São coisas diferentes.
    expect(body.posts.find((p: any) => p.post_id === "p1")).toMatchObject({ as_of: "2026-06-01T11:55:00.000Z", fetched_at: T1, snapshots: 1, metrics: { views: 1000, likes: 10 } });
  });

  it("o histórico de sincronizações diz o que cada uma fez e quando", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 10)];
    const id = await t.connect();
    await t.sync(id, { since: "2026-05-01T00:00:00.000Z", until: "2026-05-31T00:00:00.000Z" });
    const { body } = await t.runs(id);
    expect(body).toHaveLength(1);
    expect(body[0]).toMatchObject({
      status: "succeeded",
      window: { since: "2026-05-01T00:00:00.000Z", until: "2026-05-31T00:00:00.000Z" },
      started_at: T1,
      finished_at: T1,
      new_snapshots: 1,
    });
  });

  it("o token fictício nunca volta em nenhuma resposta", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 10)];
    const created = await t.call("POST", "/connections", { provider: "x", account_id: "acc_x", token: "tok-super-secreto" });
    const id = created.body.id as string;
    const everything = JSON.stringify([created.body, (await t.sync(id)).body, (await t.metrics(id)).body, (await t.runs(id)).body]);
    expect(everything).not.toContain("tok-super-secreto");
    expect(created.body).toMatchObject({ provider: "x", account_id: "acc_x", has_token: true });
  });
});

describe("idempotência: o mesmo snapshot não duplica número", () => {
  it("sincronizar de novo a mesma janela, com o mesmo snapshot, não muda os totais", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000), snap("p2", P2, T1, 2000)];
    const id = await t.connect();
    await t.sync(id);
    const again = await t.sync(id);
    expect(again.body).toMatchObject({ received: 2, new_snapshots: 0, duplicates: 2 });
    expect((await t.metrics(id)).body.totals.views).toBe(3000);
  });

  it("janelas que se sobrepõem não contam o mesmo post duas vezes", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000), snap("p2", P2, T1, 2000), snap("p3", P3, T1, 4000)];
    const id = await t.connect();
    const a = await t.sync(id, { since: "2026-05-19T00:00:00.000Z", until: "2026-05-26T00:00:00.000Z" }); // p1, p2
    const b = await t.sync(id, { since: "2026-05-24T00:00:00.000Z", until: "2026-05-31T00:00:00.000Z" }); // p2, p3
    expect(a.body).toMatchObject({ received: 2, new_snapshots: 2, duplicates: 0 });
    expect(b.body).toMatchObject({ received: 2, new_snapshots: 1, duplicates: 1 });
    const { body } = await t.metrics(id);
    expect(body.totals).toMatchObject({ posts: 3, views: 7000 }); // p2 entra uma vez só
  });

  it("o mesmo post com contadores maiores num snapshot mais novo ATUALIZA o número, não soma", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000), snap("p2", P2, T1, 2000)];
    const id = await t.connect();
    await t.sync(id);

    t.clock.set("2026-06-01T13:00:00.000Z");
    t.provider.posts = [snap("p1", P1, T1, 1000), snap("p2", P2, "2026-06-01T13:00:00.000Z", 2600)];
    const second = await t.sync(id);
    expect(second.body).toMatchObject({ new_snapshots: 1, duplicates: 1 });

    const { body } = await t.metrics(id);
    expect(body.totals.views).toBe(3600); // 1000 + 2600, e não 1000 + 2000 + 2600
    expect(body.posts.find((p: any) => p.post_id === "p2")).toMatchObject({ snapshots: 2, as_of: "2026-06-01T13:00:00.000Z", fetched_at: "2026-06-01T13:00:00.000Z" });
    // p1 foi buscado às 12:00 e p2 às 13:00: a métrica mais recentemente buscada é a de 13:00
    expect(body.posts.find((p: any) => p.post_id === "p1").fetched_at).toBe("2026-06-01T12:00:00.000Z");
    expect(body.last_fetched_at).toBe("2026-06-01T13:00:00.000Z");
  });

  it("last_fetched_at é a busca mais recente de qualquer post, mesmo quando esse post é o primeiro da lista", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000), snap("p2", P2, T1, 2000)];
    const id = await t.connect();
    await t.sync(id);
    t.clock.set("2026-06-01T13:00:00.000Z");
    t.provider.posts = [snap("p1", P1, "2026-06-01T13:00:00.000Z", 1500), snap("p2", P2, T1, 2000)]; // só p1 mudou
    await t.sync(id);
    const { body } = await t.metrics(id);
    expect(body.posts.map((p: any) => [p.post_id, p.fetched_at])).toEqual([["p1", "2026-06-01T13:00:00.000Z"], ["p2", T1]]);
    expect(body.last_fetched_at).toBe("2026-06-01T13:00:00.000Z");
  });

  it("um snapshot mais antigo que o atual entra no histórico, mas não substitui o número", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, "2026-06-01T13:00:00.000Z", 5000)];
    const id = await t.connect();
    await t.sync(id);

    t.provider.posts = [snap("p1", P1, "2026-06-01T09:00:00.000Z", 900)]; // chegou atrasado
    const late = await t.sync(id);
    expect(late.body).toMatchObject({ new_snapshots: 1, stale: 1, duplicates: 0 });
    const { body } = await t.metrics(id);
    expect(body.totals.views).toBe(5000);
    expect(body.posts[0]).toMatchObject({ snapshots: 2, as_of: "2026-06-01T13:00:00.000Z" });
  });

  it("a resposta do provedor com o mesmo item duplicado dentro dela conta uma vez só", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000), snap("p2", P2, T1, 2000)];
    t.provider.duplicateEachItem = true;
    const id = await t.connect();
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ received: 4, new_snapshots: 2, duplicates: 2 });
    expect((await t.metrics(id)).body.totals.views).toBe(3000);
  });

  it("segue a paginação até o fim e o duplicado que cruza páginas também conta uma vez", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1), snap("p2", P2, T1, 2), snap("p3", P3, T1, 4)];
    t.provider.pageSize = 2;
    const id = await t.connect();
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ pages: 2, received: 3, new_snapshots: 3 });
    expect(t.provider.calls.map((c) => c.cursor)).toEqual([null, "2"]);

    // pagina de novo o mesmo conteúdo: tudo é duplicado
    const again = await t.sync(id);
    expect(again.body).toMatchObject({ pages: 2, new_snapshots: 0, duplicates: 3 });
    expect((await t.metrics(id)).body.totals.views).toBe(7);
  });

  it("um cursor que se repete não vira laço infinito: a sync falha na hora, com o motivo", async () => {
    const t = setup(); // teto de páginas padrão (50): quem para o laço é a detecção do cursor repetido
    t.provider.posts = [snap("p1", P1, T1, 1), snap("p2", P2, T1, 2)];
    t.provider.pageSize = 1;
    t.provider.stuckCursor = true;
    const id = await t.connect();
    const run = await t.sync(id);
    expect(run.status).toBe(502);
    expect(run.body).toMatchObject({ status: "failed", error: "pagination_loop" });
    expect(t.provider.calls).toHaveLength(2); // a segunda página devolveu o mesmo cursor: parou aí
  });

  it("um provedor que nunca para de dar páginas novas esbarra no teto de páginas, e o que já chegou fica guardado", async () => {
    const t = setup({ maxPages: 3 });
    t.provider.posts = Array.from({ length: 10 }, (_, i) => snap(`p${i}`, `2026-05-${String(10 + i).padStart(2, "0")}T10:00:00.000Z`, T1, 10));
    t.provider.pageSize = 1;
    const id = await t.connect();
    const run = await t.sync(id);
    expect(run.status).toBe(502);
    expect(run.body).toMatchObject({ status: "failed", error: "too_many_pages", pages: 3, new_snapshots: 3 });
    expect(t.provider.calls).toHaveLength(3); // nem uma página além do teto
    expect((await t.metrics(id)).body.totals.posts).toBe(3);
  });

  it("um erro que não é do provedor (um defeito nosso) não é repetido: a sync falha na hora, com o motivo", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1)];
    t.provider.failNext(new TypeError("campo indefinido"));
    const id = await t.connect();
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "failed", attempts: 1, waits_ms: [] });
    expect(run.body.error).toBe("unexpected: TypeError"); // a classe, nunca a mensagem
    expect(t.provider.calls).toHaveLength(1);
  });

  it("itens que o provedor mandou inválidos são contados e não entram nos totais", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, T1, 1000)];
    t.provider.invalidPerPage = 2;
    const id = await t.connect();
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ received: 1, new_snapshots: 1, invalid: 2 });
    expect((await t.metrics(id)).body.totals.views).toBe(1000);
  });
});

describe("falha transitória: retry com limite", () => {
  async function withOnePost(options?: Parameters<typeof setup>[0]) {
    const t = setup(options);
    t.provider.posts = [snap("p1", P1, T1, 1000)];
    return { t, id: await t.connect() };
  }

  it("timeout seguido de sucesso: tenta de novo depois de 200 ms", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(timeout());
    const run = await t.sync(id);
    expect(run.status).toBe(200);
    expect(run.body).toMatchObject({ status: "succeeded", attempts: 2, waits_ms: [200], started_at: T1, finished_at: "2026-06-01T12:00:00.200Z" });
    expect(t.clock.waits).toEqual([200]);
  });

  it("3 erros 5xx e depois sucesso: espera 200, 400 e 800 ms (exponencial)", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(server(), server(503), server());
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "succeeded", attempts: 4, waits_ms: [200, 400, 800] });
    expect((await t.metrics(id)).body.totals.views).toBe(1000);
  });

  it("falha persistente: para no teto de tentativas, sem laço infinito", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(...Array.from({ length: 50 }, () => server()));
    const run = await t.sync(id);
    expect(run.status).toBe(502);
    expect(run.body).toMatchObject({ status: "failed", attempts: 4, waits_ms: [200, 400, 800], new_snapshots: 0 });
    expect(run.body.error).toMatch(/server/);
    expect(t.provider.calls).toHaveLength(4);
  });

  it("erro de rede também tem o mesmo limite", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(...Array.from({ length: 50 }, () => network()));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "failed", attempts: 4 });
    expect(run.body.error).toMatch(/network/);
  });

  it("o teto de tentativas é configurável", async () => {
    const { t, id } = await withOnePost({ policy: { maxAttempts: 2 } });
    t.provider.failNext(...Array.from({ length: 50 }, () => timeout()));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "failed", attempts: 2, waits_ms: [200] });
  });

  it("erro do cliente (token recusado) não adianta repetir: falha na primeira tentativa", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(client(401));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "failed", attempts: 1, waits_ms: [] });
    expect(run.body.error).toMatch(/401/);
    expect(t.provider.calls).toHaveLength(1);
  });

  it("o retry é da página que falhou: a anterior não é buscada de novo e nada duplica", async () => {
    const { t, id } = await withOnePost();
    t.provider.posts = [snap("p1", P1, T1, 1), snap("p2", P2, T1, 2), snap("p3", P3, T1, 4)];
    t.provider.pageSize = 2;
    t.provider.failOnCall(2, timeout()); // a segunda chamada (página 2) falha uma vez
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "succeeded", pages: 2, attempts: 3, new_snapshots: 3 });
    expect(t.provider.calls.map((c) => c.cursor)).toEqual([null, "2", "2"]);
    expect((await t.metrics(id)).body.totals.views).toBe(7);
  });

  it("falha na segunda página guarda a primeira, e uma nova sync completa sem duplicar", async () => {
    const { t, id } = await withOnePost({ policy: { maxAttempts: 1 } });
    t.provider.posts = [snap("p1", P1, T1, 1), snap("p2", P2, T1, 2), snap("p3", P3, T1, 4)];
    t.provider.pageSize = 2;
    t.provider.failOnCall(2, server());
    const failed = await t.sync(id);
    expect(failed.body).toMatchObject({ status: "failed", pages: 1, new_snapshots: 2 });
    expect((await t.metrics(id)).body.totals.views).toBe(3);

    const retried = await t.sync(id);
    expect(retried.body).toMatchObject({ status: "succeeded", new_snapshots: 1, duplicates: 2 });
    expect((await t.metrics(id)).body.totals.views).toBe(7);
  });
});

describe("429 com Retry-After", () => {
  async function withOnePost(options?: Parameters<typeof setup>[0]) {
    const t = setup(options);
    t.provider.posts = [snap("p1", P1, T1, 1000)];
    return { t, id: await t.connect() };
  }

  it("espera exatamente o Retry-After que o provedor mandou e tenta de novo", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(limited(7000));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "succeeded", attempts: 2, waits_ms: [7000], finished_at: "2026-06-01T12:00:07.000Z" });
    expect(t.clock.waits).toEqual([7000]);
    // a segunda chamada aconteceu 7 s depois da primeira, nem antes
    expect(t.provider.calls[1]!.at.getTime() - t.provider.calls[0]!.at.getTime()).toBe(7000);
  });

  it("Retry-After 0 tenta de novo na hora", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(limited(0));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "succeeded", attempts: 2, waits_ms: [0] });
  });

  it("a espera não passa do teto: no teto exato espera, acima dele adia sem esperar", async () => {
    const exactly = await withOnePost({ policy: { maxRetryAfterMs: 10_000 } });
    exactly.t.provider.failNext(limited(10_000));
    expect((await exactly.t.sync(exactly.id)).body).toMatchObject({ status: "succeeded", waits_ms: [10_000] });

    const above = await withOnePost({ policy: { maxRetryAfterMs: 10_000 } });
    above.t.provider.failNext(limited(10_001));
    const run = await above.t.sync(above.id);
    expect(run.status).toBe(202);
    expect(run.body).toMatchObject({ status: "deferred", attempts: 1, waits_ms: [], retry_at: "2026-06-01T12:00:10.001Z" });
    expect(above.t.clock.waits).toEqual([]); // nenhuma espera
    expect(above.t.provider.calls).toHaveLength(1); // e nenhuma tentativa antes da hora
  });

  it("Retry-After de 2 minutos, com teto de 30 s, adia para daqui a 2 minutos sem tentar antes", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(limited(120_000));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "deferred", retry_at: "2026-06-01T12:02:00.000Z" });
    expect((await t.runs(id)).body[0]).toMatchObject({ status: "deferred", retry_at: "2026-06-01T12:02:00.000Z" });
    expect((await t.metrics(id)).body.totals.views).toBe(0);

    t.clock.set("2026-06-01T12:02:00.000Z"); // chegou a hora
    const later = await t.sync(id);
    expect(later.body.status).toBe("succeeded");
    expect((await t.metrics(id)).body.totals.views).toBe(1000);
  });

  it("429 repetidos gastam as tentativas e terminam adiados, não em laço", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(...Array.from({ length: 50 }, () => limited(2000)));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "deferred", attempts: 4, waits_ms: [2000, 2000, 2000], retry_at: "2026-06-01T12:00:08.000Z" });
    expect(t.provider.calls).toHaveLength(4);
  });

  it("429 seguido de timeout: cada falha tem a sua espera (Retry-After, depois backoff da 2ª tentativa)", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(limited(3000), timeout());
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "succeeded", attempts: 3, waits_ms: [3000, 400] });
  });

  it("429 sem Retry-After usa o backoff", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(limited(null), limited(null));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "succeeded", attempts: 3, waits_ms: [200, 400] });
  });

  it("429 sem Retry-After para sempre falha no teto de tentativas", async () => {
    const { t, id } = await withOnePost();
    t.provider.failNext(...Array.from({ length: 50 }, () => limited(null)));
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "failed", attempts: 4 });
  });
});

describe("entrada", () => {
  it("cadastra a conexão só com rede conhecida, conta e token", async () => {
    const t = setup();
    expect((await t.call("POST", "/connections", { provider: "orkut", account_id: "a", token: "t" })).status).toBe(400);
    expect((await t.call("POST", "/connections", { provider: "x", account_id: "", token: "t" })).status).toBe(400);
    expect((await t.call("POST", "/connections", { provider: "x", account_id: "a" })).status).toBe(400);
    expect((await t.call("POST", "/connections", { provider: "x", account_id: "a", token: "t" })).status).toBe(201);
    const duplicate = await t.call("POST", "/connections", { provider: "x", account_id: "a", token: "t2" });
    expect(duplicate.status).toBe(409);
    expect(duplicate.body.error).toBe("duplicate_connection");
  });

  it.each([
    ["sem janela", {}],
    ["since depois de until", { since: "2026-06-02T00:00:00.000Z", until: "2026-06-01T00:00:00.000Z" }],
    ["data impossível", { since: "2026-02-30T00:00:00Z", until: "2026-03-01T00:00:00Z" }],
    ["data sem fuso", { since: "2026-06-01T00:00:00", until: "2026-06-02T00:00:00" }],
  ])("sync %s é 400 e não chama o provedor", async (_name, body) => {
    const t = setup();
    const id = await t.connect();
    expect((await t.call("POST", `/connections/${id}/sync`, body)).status).toBe(400);
    expect(t.provider.calls).toHaveLength(0);
    expect((await t.runs(id)).body).toEqual([]);
  });

  it("janela com since igual a until é válida", async () => {
    const t = setup();
    const id = await t.connect();
    expect((await t.sync(id, { since: "2026-06-01T00:00:00.000Z", until: "2026-06-01T00:00:00.000Z" })).status).toBe(200);
  });

  it("conexão inexistente é 404 em todas as rotas", async () => {
    const t = setup();
    expect((await t.sync("nada", ALL)).status).toBe(404);
    expect((await t.metrics("nada")).status).toBe(404);
    expect((await t.runs("nada")).status).toBe(404);
  });
});

test/conflicts.test.ts.source:
import { describe, expect, it } from "vitest";
import { server, snap } from "./fakes.ts";
import { setup } from "./helpers.ts";

const P1 = "2026-05-20T10:00:00.000Z";
const P2 = "2026-05-25T10:00:00.000Z";
const AS_OF = "2026-06-01T11:00:00.000Z";
const T1 = "2026-06-01T12:00:00.000Z";

describe("o mesmo post e o mesmo as_of com contadores diferentes é conflito, não repetição", () => {
  it("100 e depois 999: o canônico fica, os totais não mudam, e o conflito aparece separado de duplicates", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100, { likes: 5 })];
    const id = await t.connect();
    await t.sync(id);
    t.provider.posts = [snap("p1", P1, AS_OF, 999, { likes: 5 })];
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "succeeded", new_snapshots: 0, duplicates: 0, conflicts: 1, stale: 0 });
    const { body } = await t.metrics(id);
    expect(body.totals).toMatchObject({ posts: 1, views: 100, likes: 5 });
    expect(body.posts[0]).toMatchObject({ snapshots: 1, metrics: { views: 100 } });
    expect(body.conflicts).toEqual([
      {
        post_id: "p1",
        as_of: AS_OF,
        canonical: { views: 100, likes: 5, comments: 0, shares: 0 },
        observed: { views: 999, likes: 5, comments: 0, shares: 0 },
        occurrences: 1,
        first_seen_at: T1,
        last_seen_at: T1,
      },
    ]);
  });

  it("repetir o mesmo conflito conta a ocorrência mas não cria registros novos", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    await t.sync(id);
    t.provider.posts = [snap("p1", P1, AS_OF, 999)];
    for (let i = 0; i < 5; i += 1) await t.sync(id);
    const { conflicts } = (await t.metrics(id)).body;
    expect(conflicts).toHaveLength(1);
    expect(conflicts[0]).toMatchObject({ occurrences: 5 });
  });

  it("um valor contraditório diferente é outro registro", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    await t.sync(id);
    for (const views of [999, 777]) {
      t.provider.posts = [snap("p1", P1, AS_OF, views)];
      await t.sync(id);
    }
    expect((await t.metrics(id)).body.conflicts.map((c: any) => c.observed.views).sort()).toEqual([777, 999]);
  });

  it.each([["likes", { likes: 9 }], ["comments", { comments: 9 }], ["shares", { shares: 9 }]])("só %s diferente também é conflito", async (_name, change) => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    await t.sync(id);
    t.provider.posts = [snap("p1", P1, AS_OF, 100, change)];
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ conflicts: 1, duplicates: 0 });
    expect((await t.metrics(id)).body.totals).toMatchObject({ likes: 0, comments: 0, shares: 0 });
  });

  it("a repetição idêntica continua duplicate e não gera conflito", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    await t.sync(id);
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ duplicates: 1, conflicts: 0 });
    expect((await t.metrics(id)).body.conflicts).toEqual([]);
  });

  it("um conflito não interrompe o lote: os outros posts da mesma página entram", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    await t.sync(id);
    t.provider.posts = [snap("p1", P1, AS_OF, 999), snap("p2", P2, AS_OF, 50)];
    const run = await t.sync(id);
    expect(run.body).toMatchObject({ status: "succeeded", new_snapshots: 1, conflicts: 1 });
    expect((await t.metrics(id)).body.totals).toMatchObject({ posts: 2, views: 150 });
  });

  it("o mesmo conflito dentro da mesma resposta conta cada ocorrência uma vez", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    await t.sync(id);
    t.provider.posts = [snap("p1", P1, AS_OF, 999)];
    t.provider.duplicateEachItem = true; // a resposta traz o item contraditório duas vezes
    const run = await t.sync(id);
    expect(run.body.conflicts).toBe(2);
    expect((await t.metrics(id)).body.conflicts).toMatchObject([{ occurrences: 2 }]);
  });
});

describe("last_checked_at: quando o post foi consultado com sucesso pela última vez", () => {
  it("existe ao lado de fetched_at e as_of, que mantêm o significado", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    await t.sync(id);
    const { body } = await t.metrics(id);
    expect(body.posts[0]).toMatchObject({ as_of: AS_OF, fetched_at: T1, last_checked_at: T1 });
    expect(body.last_checked_at).toBe(T1);
  });

  it("o last_checked_at geral é o do post consultado mais recentemente", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100), snap("p2", P2, AS_OF, 50)];
    const id = await t.connect();
    await t.sync(id);
    t.clock.set("2026-06-02T09:00:00.000Z");
    t.provider.posts = [snap("p2", P2, AS_OF, 50)];
    await t.sync(id);
    const { body } = await t.metrics(id);
    expect(body.posts.map((p: any) => p.last_checked_at)).toEqual([T1, "2026-06-02T09:00:00.000Z"]);
    expect(body.last_checked_at).toBe("2026-06-02T09:00:00.000Z");
    expect(body.last_fetched_at).toBe(T1);
  });

  it("receber o mesmo snapshot de novo confirma a consulta: last_checked_at avança, fetched_at e as_of não", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    await t.sync(id);
    t.clock.set("2026-06-02T09:00:00.000Z");
    await t.sync(id);
    expect((await t.metrics(id)).body.posts[0]).toMatchObject({ as_of: AS_OF, fetched_at: T1, last_checked_at: "2026-06-02T09:00:00.000Z" });
  });

  it("falha da sync e post ausente da resposta não avançam o campo", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100), snap("p2", P2, AS_OF, 50)];
    const id = await t.connect();
    await t.sync(id);
    t.clock.set("2026-06-02T09:00:00.000Z");
    t.provider.failNext(server(), server(), server(), server());
    expect((await t.sync(id)).body.status).toBe("failed");
    expect((await t.metrics(id)).body.posts.map((p: any) => p.last_checked_at)).toEqual([T1, T1]);

    t.provider.posts = [snap("p1", P1, AS_OF, 100)]; // o p2 sumiu da resposta
    t.clock.set("2026-06-02T09:00:00.000Z");
    await t.sync(id);
    const posts = (await t.metrics(id)).body.posts;
    expect(posts.find((p: any) => p.post_id === "p1").last_checked_at).toBe("2026-06-02T09:00:00.000Z");
    expect(posts.find((p: any) => p.post_id === "p2").last_checked_at).toBe(T1);
  });

  it("uma resposta mais antiga que chega depois não faz o campo regredir", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, AS_OF, 100)];
    const id = await t.connect();
    t.clock.set("2026-06-03T00:00:00.000Z");
    await t.sync(id);
    t.clock.set("2026-06-02T00:00:00.000Z"); // o relógio desta sync é anterior (resposta fora de ordem)
    await t.sync(id);
    expect((await t.metrics(id)).body.posts[0].last_checked_at).toBe("2026-06-03T00:00:00.000Z");
  });

  it("um snapshot mais antigo que o atual (stale) também confirma a consulta do post, sem mudar o número atual", async () => {
    const t = setup();
    t.provider.posts = [snap("p1", P1, "2026-06-01T11:00:00.000Z", 200)];
    const id = await t.connect();
    await t.sync(id);
    t.clock.set("2026-06-02T09:00:00.000Z");
    t.provider.posts = [snap("p1", P1, "2026-06-01T10:00:00.000Z", 150)];
    await t.sync(id);
    expect((await t.metrics(id)).body.posts[0]).toMatchObject({ metrics: { views: 200 }, last_checked_at: "2026-06-02T09:00:00.000Z" });
  });
});

test/error-safety.test.ts.source:
import { describe, expect, it } from "vitest";
import { ConfigError, loadConfig, originOf } from "../src/config.ts";
import { HttpMetricsProvider } from "../src/providers/http.ts";
import { ProviderError } from "../src/providers/port.ts";
import { client, server } from "./fakes.ts";
import { openDatabase } from "../src/db.ts";
import { activeCooldown, listRuns, normalizeStoredError } from "../src/store.ts";
import { setup } from "./helpers.ts";
import { ALL } from "./helpers.ts";

const SECRET = "tok-SINTETICO-9f3a7c";
const everything = (...values: unknown[]) => JSON.stringify(values);

async function failingRun(error: Error) {
  const t = setup();
  const id = await t.connect("instagram", "acc_1", SECRET);
  t.provider.failNext(error, error, error, error); // as 4 tentativas da política, para a falha ser a última
  const run = await t.sync(id);
  const history = await t.runs(id);
  return { t, id, run, history };
}

describe("mensagens de erro não expõem credenciais", () => {
  it("erro inesperado de um adapter com o token na mensagem: nem a resposta nem o histórico o carregam, e a categoria fica", async () => {
    const { run, history } = await failingRun(new Error(`falhou ao autenticar com ${SECRET}`));
    expect(run.status).toBe(502);
    expect(run.body).toMatchObject({ status: "failed", error: "unexpected: Error" });
    expect(everything(run.body, history.body)).not.toContain(SECRET);
  });

  it("erro tipado do provedor com o segredo na mensagem: fica a categoria e o status HTTP, não a mensagem", async () => {
    const { run, history } = await failingRun(new ProviderError("server", `500 em https://api.exemplo/?access_token=${SECRET}`, 503));
    expect(run.body.error).toBe("server (503)");
    expect(everything(run.body, history.body)).not.toContain(SECRET);
  });

  it("erro do cliente (401) mantém o código", async () => {
    const { run } = await failingRun(client(401));
    expect(run.body.error).toBe("client (401)");
  });

  it("o nome de classe só entra se for de uma classe conhecida: um nome que parece um identificador (ou um token) vira Error", async () => {
    class TokenNamed extends Error {
      constructor() {
        super("x");
        this.name = SECRET.replace(/-/g, "_"); // alfanumérico e curto: passaria numa regex, não numa lista
      }
    }
    const { run, history } = await failingRun(new TokenNamed());
    expect(run.body.error).toBe("unexpected: Error");
    expect(everything(run.body, history.body)).not.toContain(SECRET.replace(/-/g, "_"));
    const known = await failingRun(new RangeError("fora da faixa"));
    expect(known.run.body.error).toBe("unexpected: RangeError");
  });

  it.each([
    ["timeout", "timeout"],
    ["network", "network"],
  ])("falha tipada sem status HTTP (%s) vira só a categoria", async (kind) => {
    const { run } = await failingRun(new ProviderError(kind as "timeout" | "network", `sem resposta, token ${SECRET}`));
    expect(run.body.error).toBe(kind);
  });

  it.each([["uma string", `falha com ${SECRET}`], ["um número", 42], ["um objeto sem nome", { message: SECRET }]])("lançar %s também vira texto seguro", async (_name, thrown) => {
    const { run, history } = await failingRun(thrown as Error);
    expect(run.body.error).toBe("unexpected: Error");
    expect(everything(run.body, history.body)).not.toContain(SECRET);
  });

  it("o erro persistido e o devolvido são o mesmo texto seguro", async () => {
    const { run, history } = await failingRun(server(502));
    expect(history.body[0].error).toBe(run.body.error);
  });
});

describe("o cliente HTTP não copia texto arbitrário para os erros", () => {
  const fetching = (error: unknown) => new HttpMetricsProvider({ baseUrl: "http://provedor.invalido", network: "x", fetch: (async () => Promise.reject(error)) as typeof fetch });
  const request = { account: "acc_1", token: SECRET, since: ALL.since, until: ALL.until, cursor: null };
  const errorOf = async (promise: Promise<unknown>) => (await promise.then(() => null, (e: ProviderError) => e)) as ProviderError;

  it("rede fora do ar com o segredo na mensagem: o ProviderError traz só a classe conhecida e, no detalhe, o código de sistema", async () => {
    const cause = Object.assign(new Error(`connect ECONNREFUSED com ${SECRET}`), { code: "ECONNREFUSED" });
    const error = await errorOf(fetching(new TypeError(`fetch failed ${SECRET}`, { cause })).fetchPosts(request));
    expect(error.kind).toBe("network");
    expect(error.message).not.toContain(SECRET);
    expect(error.message).toContain("TypeError");
    expect(error.detail).toBe("ECONNREFUSED");
  });

  it("o código de sistema só entra se tiver a forma de um (ECONNREFUSED, UND_ERR_...), e o nome só se for conhecido", async () => {
    const weird = Object.assign(new TypeError("x", { cause: Object.assign(new Error("y"), { code: `ECONN ${SECRET}` }) }), { name: `Erro ${SECRET}` });
    const error = await errorOf(fetching(weird).fetchPosts(request));
    expect(error.message).not.toContain(SECRET);
    expect(error.detail).toBeUndefined();
    const named = Object.assign(new TypeError("z", { cause: Object.assign(new Error("w"), { code: "ECONNREFUSED" }) }), {});
    expect((await errorOf(fetching(named).fetchPosts(request))).detail).toBe("ECONNREFUSED");
    const tokenLike = Object.assign(new Error("z"), { code: SECRET.replace(/-/g, "_") });
    expect((await errorOf(fetching(tokenLike).fetchPosts(request))).detail).toBeUndefined();
    const undici = Object.assign(new Error("z"), { code: "UND_ERR_SOCKET" });
    expect((await errorOf(fetching(undici).fetchPosts(request))).detail).toBe("UND_ERR_SOCKET");
  });

  it("o detalhe seguro chega ao histórico: o operador distingue recusa de conexão, timeout de corpo e JSON inválido", async () => {
    const refused = new HttpMetricsProvider({
      baseUrl: "http://provedor.invalido",
      network: "x",
      fetch: (async () => Promise.reject(Object.assign(new TypeError(`falhou ${SECRET}`), { cause: { code: "ECONNREFUSED" } }))) as typeof fetch,
    });
    const t = setup();
    const id = await t.connect("instagram", "acc_1", SECRET);
    t.provider.failNext(await errorOf(refused.fetchPosts(request)), await errorOf(refused.fetchPosts(request)), await errorOf(refused.fetchPosts(request)), await errorOf(refused.fetchPosts(request)));
    const run = await t.sync(id);
    expect(run.body.error).toBe("network: ECONNREFUSED");
    expect(everything(run.body, (await t.runs(id)).body)).not.toContain(SECRET);

    const notJson = new HttpMetricsProvider({ baseUrl: "http://p.invalido", network: "x", fetch: (async () => new Response("<html>", { status: 200 })) as typeof fetch });
    const bodyTimeout = new HttpMetricsProvider({
      baseUrl: "http://p.invalido",
      network: "x",
      fetch: (async () => new Response(new ReadableStream({ start: (c) => c.error(new DOMException("t", "TimeoutError")) }), { status: 200 })) as typeof fetch,
    });
    expect((await errorOf(notJson.fetchPosts(request))).detail).toBe("body_not_json");
    expect((await errorOf(bodyTimeout.fetchPosts(request))).detail).toBe("body");
  });

  it("kind e status inesperados (adapter que monta ProviderError com texto) não chegam ao histórico", async () => {
    const forged = new ProviderError(`server ${SECRET}` as never, "x", `503 ${SECRET}` as never, null, `detalhe ${SECRET}`);
    const { run, history } = await failingRun(forged);
    expect(run.body.error).toBe("unexpected: ProviderError");
    expect(everything(run.body, history.body)).not.toContain(SECRET);
    const badStatus = await failingRun(new ProviderError("server", "x", 99_999));
    expect(badStatus.run.body.error).toBe("server");
  });

  it("linhas antigas do histórico, gravadas com texto livre, saem normalizadas na leitura", async () => {
    const t = setup();
    const id = await t.connect("instagram", "acc_1", SECRET);
    await t.sync(id);
    // simula um banco anterior a esta correção
    const db = (t as unknown as { db: ReturnType<typeof openDatabase> }).db;
    db.prepare("UPDATE sync_runs SET error = ? WHERE connection_id = ?").run(`unexpected: falhou com ${SECRET} na conta`, id);
    const legacy = (await t.runs(id)).body[0].error as string;
    expect(legacy).toBe("unexpected: Error");
    db.prepare("UPDATE sync_runs SET error = ? WHERE connection_id = ?").run("server: o provedor respondeu 503 em https://x/?access_token=" + SECRET, id);
    expect((await t.runs(id)).body[0].error).toBe("server (503)");
    expect(listRuns(db, id)[0]!.error).toBe("server (503)");
  });

  it("corpo interrompido com o segredo na mensagem também não vaza", async () => {
    const body = new Response(new ReadableStream({ start: (c) => c.error(new TypeError(`terminated ${SECRET}`)) }), { status: 200 });
    const provider = new HttpMetricsProvider({ baseUrl: "http://provedor.invalido", network: "x", fetch: (async () => body) as typeof fetch });
    const error = await errorOf(provider.fetchPosts(request));
    expect(error.kind).toBe("network");
    expect(error.message).not.toContain(SECRET);
  });
});

describe("configuração e log de inicialização", () => {
  it("o log mostra só a origem: sem usuário, senha, caminho, query nem hash", () => {
    expect(originOf("https://usuario:senha@api.exemplo:8443/v1/SEGREDO/posts?access_token=abc#frag")).toBe("https://api.exemplo:8443");
    expect(originOf("http://127.0.0.1:4011")).toBe("http://127.0.0.1:4011");
    expect(originOf("isso não é uma url")).toBe("(URL inválida)");
  });

  it.each([
    ["com protocolo errado e credenciais", "ftp://usuario:S3NH4-secreta@api.exemplo/x?token=abc"],
    ["sem protocolo, com usuário e senha", "u:S3NH4-secreta@api.exemplo/x"],
    ["só usuário@host", "S3NH4-secreta@api.exemplo/x"],
    ["senha com barra sem codificar", "https://u:pa/S3NH4-secreta@host/x"],
    ["um token colado no lugar da URL", "token=S3NH4-secreta"],
  ])("PROVIDER_URL inválida (%s) não é repetida na mensagem de erro", (_name, value) => {
    try {
      loadConfig({ PROVIDER_URL: value });
      throw new Error("deveria ter falhado");
    } catch (error) {
      expect(error).toBeInstanceOf(ConfigError);
      expect((error as ConfigError).message).not.toContain("S3NH4-secreta");
      expect((error as ConfigError).message).toMatch(/PROVIDER_URL deve ser uma URL http ou https/);
    }
  });
});

describe("normalização do que já estava gravado", () => {
  it.each([
    [null, null],
    ["timeout", "timeout"],
    ["server (503)", "server (503)"],
    ["network: ECONNREFUSED", "network: ECONNREFUSED"],
    ["client (401)", "client (401)"],
    ["unexpected: TypeError", "unexpected: TypeError"],
    ["rate_limited: o provedor pediu para esperar 120000 ms", "rate_limited: o provedor pediu para esperar 120000 ms"],
    ["too_many_pages", "too_many_pages"],
    ["pagination_loop", "pagination_loop"],
    ["cooldown_active", "cooldown_active"],
  ])("forma segura %j é mantida", (input, expected) => {
    expect(normalizeStoredError(input)).toBe(expected);
  });

  it.each([
    ["unexpected: falhou com tok-1 na conta", "unexpected: Error"],
    ["antes unexpected: TypeError", "unexpected: Error"],
    ["unexpected: TypeError e mais texto com tok-2", "unexpected: Error"],
    ["server: o provedor respondeu 503", "server (503)"],
    ["server (503) com segredo tok-3", "server (503)"],
    ["rate_limited: o provedor pediu para esperar 5 ms e depois tok-4", "rate_limited"],
    ["rate_limited: o provedor pediu para esperar 5 ms (acima do máximo representável; cooldown fixado em 9999-12-31T23:59:59.999Z)", "rate_limited: o provedor pediu para esperar 5 ms (acima do máximo representável; cooldown fixado em 9999-12-31T23:59:59.999Z)"],
    ["rate_limited: o provedor pediu para esperar 5 ms (cooldown fixado em tok-9)", "rate_limited"],
    ["xrate_limited: o provedor pediu para esperar 5 ms", "unexpected: Error"],
    ["too_many_pages e texto", "unexpected: Error"],
    ["pagination_loopx", "unexpected: Error"],
    ["network: ECONN REFUSED tok-5", "network"],
    ["falha qualquer", "unexpected: Error"],
  ])("texto livre %j é normalizado", (input, expected) => {
    expect(normalizeStoredError(input)).toBe(expected);
  });

  it.each([
    ["unexpected: tokSECRETfa", "unexpected: Error"],
    ["unexpected: TypeError", "unexpected: TypeError"],
    ["server: tok_SECRET_9f3a", "server"],
    ["client: sk_live_abcDEF123", "client"],
    ["rate_limited: tok123", "rate_limited"],
    ["network: ECONNREFUSED", "network: ECONNREFUSED"],
    ["network: ECONNREFUSED_x", "network"],
    ["timeout: body", "timeout: body"],
    ["timeout: bodyx", "timeout"],
  ])("a forma só é aceita com valores de listas fechadas: %j → %j", (input, expected) => {
    expect(normalizeStoredError(input)).toBe(expected);
  });

  it("cooldown de conexão que não existe é nulo", () => {
    expect(activeCooldown(openDatabase(":memory:"), "nao-existe", new Date())).toBeNull();
  });
});

